const items = $input.first().json.value || [];
return items.filter(item => {
  const f = item.fields || {};
  const status = String(f.STATUS_INTEGRACAO || '').trim().toUpperCase();
  return f.NOTA_FISCAL && f.SERIE_NF && (!status || status === 'PENDENTE' || status === 'NÃO LOCALIZADO' || status === 'NAO LOCALIZADO');
}).map(item => {
  const f = item.fields;
  const nf = String(f.NOTA_FISCAL).trim();
  const serie = String(f.SERIE_NF).trim();
  if (!/^\d{1,20}$/.test(nf) || !/^\d{1,10}$/.test(serie)) return null;
  return {json:{spItemId:Number(item.id),nota:nf,serie:serie}};
}).filter(Boolean);

return $input.all().map(({json:r}) => {
 const n=Number(r.QTDE_NOTAS_ENCONTRADAS || 0);
 const status=n===0?'NÃO LOCALIZADO':n>1?'ERRO':'INTEGRADO';
 const fields={STATUS_INTEGRACAO:status};
 if(n===1 && r.CHAVE_NFE){
  fields.CHAVE_NFE=String(r.CHAVE_NFE).trim();
  fields.CANAL=r.CANAL ? String(r.CANAL).trim() : null;
  fields.MARCA=r.MARCA ? String(r.MARCA).trim() : null;
  fields.QUANTIDADE=r.QUANTIDADE===null?null:Number(r.QUANTIDADE);
  fields.VALOR=r.VALOR===null?null:Number(r.VALOR);
 }
 return {json:{spItemId:Number(r.SP_ITEM_ID),fields,diagnostico:n>1?'NF e série correspondem a mais de uma filial. Exige identificação da filial.':status}};
});
